cat > deny-specific-bucket-list.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "ExplicitDenyListBucket",
      "Effect": "Deny",
      "Action": "s3:ListBucket",
      "Resource": "arn:aws:s3:::my-single-bucket"
    }
  ]
}
EOF

cat > trust.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": { "Service": "ec2.amazonaws.com" },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF

cat > perm.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowListBucket",
      "Effect": "Allow",
      "Action": "s3:ListBucket",
      "Resource": "arn:aws:s3:::my-app-bucket"
    },
    {
      "Sid": "AllowGetObjects",
      "Effect": "Allow",
      "Action": "s3:GetObject",
      "Resource": "arn:aws:s3:::my-app-bucket/*"
    }
  ]
}
EOF

cat > perm-updated.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    { "Sid": "ListBucket", "Effect": "Allow", "Action": "s3:ListBucket", "Resource": "arn:aws:s3:::my-app-bucket" },
    { "Sid": "ReadObjects", "Effect": "Allow", "Action": "s3:GetObject", "Resource": "arn:aws:s3:::my-app-bucket/*" },
    { "Sid": "WriteObjects", "Effect": "Allow", "Action": "s3:PutObject", "Resource": "arn:aws:s3:::my-app-bucket/*" }
  ]
}
EOF

cat > boundary.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "BoundaryAllowReadOnly",
    "Effect": "Allow",
    "Action": ["s3:ListBucket", "s3:GetObject"],
    "Resource": ["arn:aws:s3:::my-boundary-bucket", "arn:aws:s3:::my-boundary-bucket/*"]
  }]
}
EOF
aws iam create-policy --policy-name ReadOnlyBoundaryPolicy --policy-document file://boundary.json

cat > managed.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "ReadTwoBuckets",
    "Effect": "Allow",
    "Action": ["s3:ListBucket", "s3:GetObject"],
    "Resource": [
      "arn:aws:s3:::managed-demo-bucket-a", "arn:aws:s3:::managed-demo-bucket-a/*",
      "arn:aws:s3:::managed-demo-bucket-b", "arn:aws:s3:::managed-demo-bucket-b/*"
    ]
  }]
}
EOF

cat > policy.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "AllowOrgRead",
    "Effect": "Allow",
    "Principal": "*",
    "Action": "s3:GetObject",
    "Resource": "arn:aws:s3:::org-locked-bucket/*",
    "Condition": { "StringEquals": { "aws:PrincipalOrgID": "o-ab12cdefgh" } }
  }]
}
EOF
aws s3api put-bucket-policy --bucket org-locked-bucket --policy file://policy.json

"Condition": {
  "Bool": { "aws:MultiFactorAuthPresent": "true" },
  "NumericLessThan": { "aws:MultiFactorAuthAge": "300" }
}

cat > trust.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Principal": { "Federated": "arn:aws:iam::ACCOUNT_ID:saml-provider/CorpIDP" },
    "Action": "sts:AssumeRoleWithSAML",
    "Condition": { "StringEquals": { "SAML:aud": "https://signin.aws.amazon.com/saml" } }
  }]
}
EOF
sed -i "s/ACCOUNT_ID/$ACCOUNT_ID/g" trust.json

cat > lambda_function.py <<'PY'
import boto3
ec2 = boto3.client('ec2')
def lambda_handler(event, context):
    event = event or {}
    resp = ec2.describe_instances(Filters=[{'Name':'tag:AutoStop','Values':['true']}])
    tagged_ids = [i['InstanceId'] for r in resp.get('Reservations', []) for i in r.get('Instances', [])]
    untagged_id = event.get('untagged_instance_id')
    out = {'tagged_found': tagged_ids, 'attempted_tagged_stop': [], 'attempted_untagged_stop': untagged_id, 'untagged_stop_error': None}
    if tagged_ids:
        ec2.stop_instances(InstanceIds=tagged_ids)
        out['attempted_tagged_stop'] = tagged_ids
    if untagged_id:
        try: ec2.stop_instances(InstanceIds=[untagged_id])
        except Exception as e: out['untagged_stop_error'] = str(e)
    return out
PY
zip -r function.zip lambda_function.py
ROLE_ARN=$(aws iam get-role --role-name "$ROLE_NAME" --query Role.Arn --output text)
aws lambda create-function --function-name "$FUNC_NAME" --runtime "$RUNTIME" --handler lambda_function.lambda_handler --zip-file fileb://function.zip --role "$ROLE_ARN"
